    void prepareToPlay(double sampleRate,int block)override{rate=sampleRate;outputLimiting=0;for(auto& limiter:outputLimiters)limiter.reset();capacity=juce::jmax(1,block);scratch.setSize(20,capacity);filtered.ensureSize(65536);for(int i=0;i<8;++i){loops[i]->setNonRealtime(isNonRealtime());loops[i]->prepareToPlay(rate,capacity);previousGain[i]=juce::Decibels::decibelsToGain(volumeDb[i].load());}}
