                std::array<std::array<float*,2>,10> destinations{};for(int pair=0;pair<10;++pair){int bus=pair==0?output[i].load():pair-1;if(bus<0||bus>8||!getBus(false,bus)->isEnabled())bus=0;auto dest=getBusBuffer(buffer,false,bus);for(int ch=0;ch<2;++ch)destinations[pair][ch]=dest.getWritePointer(ch);}
